    X.on = id => { const f = X.FEATS.find(x => x.id === id.replace(/\.auto$/, '')); const d = f ? (/\.auto$/.test(id) ? f.auto !== false : f.def !== false) : true; return FS[id] == null ? d : !!FS[id]; };
